import { zodResolver } from '@hookform/resolvers/zod';
import { Spraksjekk, checkText } from '@navikt/dab-spraksjekk';
import { Button, Select, Switch, TextField, Textarea } from '@navikt/ds-react';
import React, { RefObject, useEffect, useMemo, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { z } from 'zod';
import { logReferatFullfort, logToggleSpraksjekkToggle } from '../../../../analytics/analytics';
import { AktivitetStatus, Kanal } from '../../../../datatypes/aktivitetTypes';
import { SamtalereferatAktivitet, VeilarbAktivitetType } from '../../../../datatypes/internAktivitetTypes';
import ControlledDatePicker from '../../../../felles-komponenter/skjema/datovelger/ControlledDatePicker';
import AktivitetFormHeader from '../AktivitetFormHeader';
import CustomErrorSummary from '../CustomErrorSummary';
import { dateOrUndefined } from '../ijobb/AktivitetIjobbForm';
import { useHilsenVeilederTekst } from './useHilsenVeilederTekst';
import { TryggTekstBakFeatureToggle } from '../tryggtekst/TryggTekst';
import useAppDispatch from '../../../../felles-komponenter/hooks/useAppDispatch';
import { notifiserTryggTekstVedLagring } from '../tryggtekst/tryggtekst-slice';
import { useSamtalereferatKladd } from './useSamtalereferatKladd';
import { useSelector } from 'react-redux';
import { selectValgtPeriodeId } from '../../../filtrering/filter/valgt-periode-slice';
import { isValid } from 'date-fns';

const schema = z.object({
    tittel: z.string().min(1, 'Du må fylle ut tema for samtalen').max(100, 'Du må korte ned teksten til 100 tegn'),
    fraDato: z
        .date({
            errorMap: (issue) => {
                if (issue.code === 'invalid_type') {
                    return { message: 'Fra dato må fylles ut' };
                }
                if (issue.code === 'invalid_date') {
                    return { message: 'Ikke en gyldig dato' };
                }
                return { message: issue.message || 'Ikke en gyldig dato' };
            },
        })
        .refine((date) => date.getTime() < new Date().getTime(), {
            message: 'Dato kan ikke være etter dagens dato',
        }),
    kanal: z.nativeEnum(Kanal),
    referat: z.string().min(1, 'Du må fylle ut samtalereferat').max(5000, 'Du må korte ned teksten til 5000 tegn'),
});

export type SamtalereferatAktivitetFormValues = z.infer<typeof schema>;

interface Props {
    onSubmit: (
        data: SamtalereferatAktivitetFormValues & {
            status: string;
            avtalt: boolean;
            erReferatPublisert?: boolean;
        },
    ) => Promise<void>;
    dirtyRef: RefObject<boolean>;
    aktivitet?: SamtalereferatAktivitet;
}

const InnerSamtalereferatForm = (props: Props) => {
    const { onSubmit, dirtyRef, aktivitet } = props;
    const [open, setOpen] = useState(true);
    const startTekst = useHilsenVeilederTekst();
    const nyAktivitet = !aktivitet;
    const dispatch = useAppDispatch();
    const oppfolgingsperiodeId = useSelector(selectValgtPeriodeId);
    const { lagreSamtalereferatKladd, hentSamtaleReferatKladd, slettSamtaleReferatKladd } = useSamtalereferatKladd({
        oppfolgingsperiodeId: oppfolgingsperiodeId!,
    });
    const kladd = useMemo(() => hentSamtaleReferatKladd(), []);

    const defaultValues: Partial<SamtalereferatAktivitetFormValues> = useMemo(
        () => ({
            tittel: kladd?.tittel || aktivitet?.tittel || '',
            fraDato: dateOrUndefined(kladd?.fraDato) || dateOrUndefined(aktivitet?.fraDato),
            kanal: kladd?.kanal || aktivitet?.kanal || Kanal.TELEFON,
            referat: kladd?.referat || aktivitet?.referat || startTekst,
        }),
        [kladd, aktivitet],
    );

    const formHandlers = useForm<SamtalereferatAktivitetFormValues>({
        defaultValues,
        resolver: zodResolver(schema),
        shouldFocusError: true,
    });
    const {
        register,
        handleSubmit,
        watch,
        formState: { errors, isSubmitting, isDirty },
    } = formHandlers;

    if (dirtyRef) {
        dirtyRef.current = isDirty;
    }

    const tittelValue = watch('tittel');
    const referatValue = watch('referat'); // for <Textarea /> character-count to work
    const datoValue = watch('fraDato');
    const kanalValue = watch('kanal');

    useEffect(() => {
        lagreSamtalereferatKladd({
            tittel: tittelValue,
            referat: referatValue,
            fraDato: isValid(datoValue) ? datoValue.toISOString() : null,
            kanal: kanalValue,
        });
    }, [tittelValue, referatValue, datoValue, kanalValue]);

    const lagreOgDel = (erReferatPublisert: boolean) => {
        return handleSubmit((data) => {
            return onSubmit({
                ...data,
                status: AktivitetStatus.GJENNOMFOERT,
                avtalt: false,
                erReferatPublisert,
            }).then(
                () => {
                    const analysis = checkText(data.referat);
                    logReferatFullfort(analysis, erReferatPublisert, open);
                    slettSamtaleReferatKladd();
                    dispatch(notifiserTryggTekstVedLagring(data.referat));
                },
                (...args) => {
                    console.log('Invalid: args', args);
                },
            );
        });
    };

    return (
        <form autoComplete="off" noValidate>
            <FormProvider {...formHandlers}>
                <div className="space-y-8">
                    <AktivitetFormHeader aktivitetstype={VeilarbAktivitetType.SAMTALEREFERAT_TYPE} />

                    <TextField
                        label="Tema for samtalen (obligatorisk)"
                        id={'tittel'}
                        {...register('tittel')}
                        error={errors.tittel && errors.tittel.message}
                    />

                    <ControlledDatePicker
                        field={{ name: 'fraDato', required: true, defaultValue: defaultValues.fraDato }}
                        disabledDays={[{ after: new Date() }]}
                    />

                    <Select label="Møteform (obligatorisk)" {...register('kanal')}>
                        <option value={Kanal.OPPMOTE}>Oppmøte</option>
                        <option value={Kanal.TELEFON}>Telefonmøte</option>
                        <option value={Kanal.INTERNET}>Videomøte</option>
                    </Select>

                    {nyAktivitet && (
                        <>
                            <Textarea
                                label="Samtalereferat (obligatorisk)"
                                maxLength={5000}
                                {...register('referat')}
                                error={errors.referat && errors.referat.message}
                                value={referatValue}
                            />
                            <Switch
                                checked={open}
                                onChange={() => {
                                    setOpen(!open);
                                    logToggleSpraksjekkToggle(!open);
                                }}
                            >
                                Klarspråkhjelpen
                            </Switch>
                            <TryggTekstBakFeatureToggle value={referatValue} />
                            <Spraksjekk value={referatValue} open={open} options={{ tools: false, longWords: false }} />
                        </>
                    )}

                    <CustomErrorSummary errors={errors} />
                </div>
                <Lagreknapper isLoading={isSubmitting} isNy={nyAktivitet} lagreOgDel={lagreOgDel} />
            </FormProvider>
        </form>
    );
};

const Lagreknapper = (props: {
    isLoading: boolean;
    isNy: boolean;
    lagreOgDel: (erReferatPublisert: boolean) => (e?: React.BaseSyntheticEvent) => Promise<void>;
}) => {
    const { isLoading, isNy, lagreOgDel } = props;
    if (isNy) {
        return (
            <div className="mt-4 flex gap-4">
                <Button loading={isLoading} onClick={lagreOgDel(true)}>
                    Del med bruker
                </Button>
                <Button variant="secondary" loading={isLoading} onClick={lagreOgDel(false)}>
                    Lagre utkast
                </Button>
            </div>
        );
    }
    return (
        <Button className="mt-4" loading={isLoading} onClick={lagreOgDel(false)}>
            Lagre
        </Button>
    );
};

export default InnerSamtalereferatForm;
